import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-10-22","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-10-22","date":"2025-10-22T00:00:00.000Z","updated":"2025-10-23T00:00:00.000Z","tags":["Ceph","RGW","AI-generated code","Open-source policy","Ceph Steering Committee"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-22.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-22.md","lastUpdated":1780460162000}'),n={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-22.md"};function r(l,e,s,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="ceph-社区会议纪要" tabindex="-1">Ceph 社区会议纪要 <a class="header-anchor" href="#ceph-社区会议纪要" aria-label="Permalink to &quot;Ceph 社区会议纪要&quot;">​</a></h3><p><strong>日期</strong>: 2025-10-22<br><strong>参会人员</strong>: Nicholas, Casey, Dan 等</p><h4 id="_1-pr-合并进展-nicholas" tabindex="-1">1. <strong>PR 合并进展（Nicholas）</strong> <a class="header-anchor" href="#_1-pr-合并进展-nicholas" aria-label="Permalink to &quot;1. **PR 合并进展（Nicholas）**&quot;">​</a></h4><ul><li>Nicholas 提交的 PR 在 <code>RJWS singleton</code> 子套件测试和本地 <code>tutology</code> 测试中均通过，但在 rebase 到 <code>main</code> 分支后，部分无关测试失败。</li><li>讨论了测试失败的原因可能与 <code>RADOSGW (RGW) admin</code> 测试的长期问题有关，可能是 <code>usage show</code> 输出变更导致的。</li><li>决定合并 PR，因为早期分支测试通过且风险可控。</li><li>后续行动包括：Casey 将创建 tracker issue，优化测试用例抽象以支持本地和 <code>tutology</code> 模式；Nicholas 需在 PR 中补充成功测试的截图证明。</li></ul><h4 id="_2-ai-生成代码政策讨论-dan" tabindex="-1">2. <strong>AI 生成代码政策讨论（Dan）</strong> <a class="header-anchor" href="#_2-ai-生成代码政策讨论-dan" aria-label="Permalink to &quot;2. **AI 生成代码政策讨论（Dan）**&quot;">​</a></h4><ul><li>IBM 新政策允许在开源项目中使用 AI 生成代码，但需满足特定条件，如标注生成代码、使用特定模型。</li><li>对于非 IBM 拥有的项目（如 Ceph），需由社区决定是否允许此类贡献。</li><li>Dan 计划在 Ceph Steering Committee 上推动讨论，由基金会最终决策。</li><li>社区需明确是否要求贡献者声明 AI 生成代码。</li></ul><h4 id="_3-其他事项" tabindex="-1">3. <strong>其他事项</strong> <a class="header-anchor" href="#_3-其他事项" aria-label="Permalink to &quot;3. **其他事项**&quot;">​</a></h4><ul><li>下周会议取消，因 Sephlacon 会议冲突。</li></ul><h4 id="行动计划总结" tabindex="-1"><strong>行动计划总结</strong> <a class="header-anchor" href="#行动计划总结" aria-label="Permalink to &quot;**行动计划总结**&quot;">​</a></h4><p>| 责任人 | 任务 | 时间节点 | |--||-| | Casey | 合并 Nicholas 的 PR | 立即 | | Casey | 创建测试优化 tracker issue | 本周内 | | Dan | 在 Steering Committee 提交 AI 政策讨论 | Sephlacon 之后 | | 全体 | 审阅 AI 生成代码政策提案 | 待基金会安排 |</p>',10)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
